// Selfcare original code. Printed documents: invoices and forms, and which vendor type uses which.
//
// INVOICES (money documents, table sc_invoices + sc_invoice_items + sc_invoice_payments)
//   label, title (printed heading), prefix (default number prefix, the vendor can change it in Settings),
//   kind: invoice | receipt (money received now) | credit (credit note or refund) | order (no payment, e.g. purchase order),
//   party: who is billed, item: name of the item column, x: extra header fields [name, label, type, options],
//   tax / discount: show those columns, stock: 'out' | 'in' moves stock, terms, sign: signature boxes,
//   types: optional list of vendor type slugs that use it (default: every type of the family).
//
// FORMS (documents that used to be filled in by hand, table sc_documents, values saved as JSON)
//   label, title, prefix, perm (permission that may fill it in), party, sections: fields or a repeating table,
//   sign: signature boxes, types: optional vendor types, register: columns shown in the register / list.
//   Field = [name, label, type = text|textarea|date|time|number|select, options]. Table section = ['t', 'rows' => key, 'cols' => [[name, label, width]]].
//
// by_family: which invoices and forms each family of vendor types offers. Reports are in config/reports.php.
declare(strict_types=1);

